print("Submitted option 1 at tau=1,s=0: p0=%g, q0=%g, p0*q0=%g, u0=%g" % (ys, xs, xs*ys, u))

# Analytic derivation: q0=2*tau, p0=tau/2 => x=2tau(e^s-1), y=(tau/2)(e^s+1), u=tau^2 e^{2s}.
passing = [k for k, e in results.items() if e is None]
print("Options passing all checks:", passing)
if passing == [3]:
    print("Submitted answer (option 1): CHECK FAIL")
    print("Correct set (option 3): CHECK PASS")
else:
    print("Submitted answer (option 1): CHECK UNKNOWN")
